import React, { useState, useEffect } from 'react';

// Import 4 màn hình con từ thư mục components
import MovieList from './components/MovieList';
import ShowtimeScreen from './components/ShowtimeScreen';
import SeatScreen from './components/SeatScreen';
import AuthScreen from './components/AuthScreen';
import defaultDatabase from './data/database';

function App() {
  const [movies, setMovies] = useState(defaultDatabase.movies);
  const [showtimes, setShowtimes] = useState(defaultDatabase.showtimes);
  const [seats, setSeats] = useState(defaultDatabase.seats);
  const [bookings, setBookings] = useState(defaultDatabase.bookings);
  const [loading, setLoading] = useState(false);

  const [currentScreen, setCurrentScreen] = useState('movie-list');
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [selectedShowtime, setSelectedShowtime] = useState(null);

  useEffect(() => {
    // Khởi tạo với dữ liệu cục bộ để trang luôn hiển thị danh sách phim.
    setMovies(defaultDatabase.movies);
    setShowtimes(defaultDatabase.showtimes);
    setSeats(defaultDatabase.seats);
    setBookings(defaultDatabase.bookings);
    setLoading(false);

    // Nếu json-server đang chạy, cập nhật dữ liệu từ server.
    fetch('http://localhost:5000/db')
      .then((res) => {
        if (!res.ok) throw new Error("Không thể kết nối cổng dữ liệu!");
        return res.json();
      })
      .then((data) => {
        setMovies(data.movies || defaultDatabase.movies);
        setShowtimes(data.showtimes || defaultDatabase.showtimes);
        setSeats(data.seats || defaultDatabase.seats);
        setBookings(data.bookings || defaultDatabase.bookings);
      })
      .catch((err) => {
        console.warn("Không thể lấy dữ liệu từ json-server, dùng dữ liệu cục bộ:", err);
      });
  }, []);

  if (loading) {
    return (
      <div className="d-flex justify-content-center align-items-center min-vh-100 bg-light">
        <div className="text-center">
          <div className="spinner-border text-danger mb-2" role="status"></div>
          <h5 className="fw-bold text-secondary">Đang nạp dữ liệu từ database gốc...</h5>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-light min-vh-100 pb-5">
      {/* NAVBAR */}
      <nav className="navbar navbar-dark bg-dark mb-5 shadow">
        <div className="container">
          <span 
            className="navbar-brand mb-0 h1 fw-bold text-warning fs-3" 
            style={{ cursor: 'pointer', letterSpacing: '1px' }} 
            onClick={() => setCurrentScreen('movie-list')}
          >
            🎬 BETA CINEMA
          </span>
          {selectedMovie && currentScreen !== 'movie-list' && (
            <span className="text-white-50 d-none d-sm-inline">
              Phim đang chọn: <strong className="text-white">{selectedMovie.title}</strong>
            </span>
          )}
        </div>
      </nav>

      {/* ĐIỀU HƯỚNG MÀN HÌNH */}
      <div className="container">
        {currentScreen === 'movie-list' && (
          <MovieList 
            movies={movies} 
            showtimes={showtimes}
            onSelectMovie={(movie) => { 
              setSelectedMovie(movie); 
              setCurrentScreen('showtime-list'); 
            }}
            onGoToAuth={() => setCurrentScreen('auth')}
          />
        )}

        {currentScreen === 'showtime-list' && (
          <ShowtimeScreen 
            movie={selectedMovie} 
            showtimes={showtimes} 
            onSelectShowtime={(st) => { 
              setSelectedShowtime(st); 
              setCurrentScreen('seat-plan'); 
            }}
            onBack={() => setCurrentScreen('movie-list')} 
          />
        )}

        {currentScreen === 'seat-plan' && (
          <SeatScreen 
            showtime={selectedShowtime} 
            movie={selectedMovie}
            seats={seats}
            bookings={bookings}
            onBookingSuccess={(newBookings) => setBookings([...bookings, ...newBookings])}
            onBack={() => setCurrentScreen('showtime-list')}
          />
        )}

        {currentScreen === 'auth' && (
          <AuthScreen onBack={() => setCurrentScreen('movie-list')} />
        )}
      </div>
    </div>
  );
}

export default App;
